int sockfd;
int status;
int optval;               // Buffer to store the retrieved value
socklen_t optlen;

// 1. Prepare buffer size
optlen = sizeof(optval);

// 2. Retrieve SO_REUSEADDR option (standard socket level)
// Level: SOL_SOCKET
// Optname: SO_REUSEADDR
status = getsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR,
                    &optval, &optlen);

// If status == 0, optval contains the boolean state (0 or 1)
// If status < 0, an error occurred
// optlen is updated to the actual size stored (e.g., sizeof(int))
// For complex structures (e.g., SO_LINGER), optval is a struct pointer.
// Example: struct linger l; getsockopt(..., SO_LINGER, &l, &optlen);
